import{_ as e,o as t,c as o,a2 as s}from"./chunks/framework.DCVnL8g5.js";const m=JSON.parse('{"title":"Catálogos","description":"","frontmatter":{},"headers":[],"relativePath":"data-engineering/iceberg/06-catalogos.md","filePath":"data-engineering/iceberg/06-catalogos.md","lastUpdated":1789040978000,"isDraft":false}'),n={name:"data-engineering/iceberg/06-catalogos.md"};function r(i,a,l,c,d,p){return t(),o("div",null,[...a[0]||(a[0]=[s(`<h1 id="catalogos" tabindex="-1">Catálogos <a class="header-anchor" href="#catalogos" aria-label="Permalink to &quot;Catálogos&quot;">​</a></h1><p>La pregunta que responde un catálogo Iceberg:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>¿qué metadata.json es la versión actual de local.analytics.events?</span></span></code></pre></div><p>Sin esa respuesta no hay tabla, solo un montón de ficheros.</p><p>Documentación: <a href="https://iceberg.apache.org/docs/latest/spark-configuration/" target="_blank" rel="noreferrer">Spark catalogs</a>, <a href="https://iceberg.apache.org/rest-catalog-spec/" target="_blank" rel="noreferrer">REST Catalog</a>, <a href="https://iceberg.apache.org/docs/latest/" target="_blank" rel="noreferrer">docs</a>.</p><h2 id="catalogo-warehouse" tabindex="-1">Catálogo ≠ warehouse <a class="header-anchor" href="#catalogo-warehouse" aria-label="Permalink to &quot;Catálogo ≠ warehouse&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Catálogo</th><th>Object storage / warehouse</th></tr></thead><tbody><tr><td>Qué guarda</td><td>Nombres, namespaces, <strong>puntero</strong> al metadata actual</td><td>Data files, delete files, metadata JSON, manifests</td></tr><tr><td>Quién coordina commits</td><td>El catálogo (CAS / transacción / API)</td><td>El FileIO lee y escribe bytes</td></tr><tr><td>Ejemplo</td><td>REST, Hive metastore, JDBC</td><td>S3, ADLS, GCS, HDFS, local</td></tr></tbody></table><p><code>DROP TABLE</code> <em>managed</em> puede borrar el warehouse; una tabla con <code>location</code> explícita suele ser <em>unmanaged</em>. El catálogo no es Glue, Snowflake, Databricks ni BigQuery: esos pueden <strong>implementar</strong> o integrar un catálogo compatible. Iceberg OSS no los exige.</p><h2 id="opciones-oss-vigentes" tabindex="-1">Opciones OSS vigentes <a class="header-anchor" href="#opciones-oss-vigentes" aria-label="Permalink to &quot;Opciones OSS vigentes&quot;">​</a></h2><p>En <code>spark.sql.catalog.&lt;name&gt;.type</code>:</p><table tabindex="0"><thead><tr><th><code>type</code></th><th>Papel</th></tr></thead><tbody><tr><td><code>hadoop</code></td><td>Warehouse de directorios. Simple; débil para muchos writers / varios clusters.</td></tr><tr><td><code>hive</code></td><td>Hive Metastore guarda la entrada y el metadata location.</td></tr><tr><td><code>rest</code></td><td>Cliente habla <strong>REST Catalog API</strong>; detrás hay una implementación.</td></tr><tr><td><code>jdbc</code></td><td>Metastore en una base SQL.</td></tr></tbody></table><p>También aparecen <code>glue</code> y <code>nessie</code> como implementaciones. No son el núcleo pedagógico.</p><p><code>SparkCatalog</code> carga solo Iceberg. <code>SparkSessionCatalog</code> delega lo no-Iceberg al catálogo built-in de Spark (mismo metastore Hive, por ejemplo).</p><h2 id="rest-catalog" tabindex="-1">REST Catalog <a class="header-anchor" href="#rest-catalog" aria-label="Permalink to &quot;REST Catalog&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>motor (Spark, Trino, Flink, …)</span></span>
<span class="line"><span>        ↓  HTTP JSON (REST Catalog API)</span></span>
<span class="line"><span>servidor de catálogo</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>implementación (JDBC, Hive, custom, cloud…)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>puntero al metadata.json</span></span></code></pre></div><p>REST <strong>no</strong> sirve los Parquet por HTTP. Estandariza <em>cómo</em> un motor crea tablas, lista namespaces y commitea el puntero. Varios motores contra el mismo REST es el patrón multi-engine actual.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spark.sql.catalog.lake = org.apache.iceberg.spark.SparkCatalog</span></span>
<span class="line"><span>spark.sql.catalog.lake.type = rest</span></span>
<span class="line"><span>spark.sql.catalog.lake.uri = http://catalog:8181</span></span></code></pre></div><h2 id="commits-atomicos" tabindex="-1">Commits atómicos <a class="header-anchor" href="#commits-atomicos" aria-label="Permalink to &quot;Commits atómicos&quot;">​</a></h2><p>El writer:</p><ol><li>escribe data/delete files y el <strong>nuevo</strong> metadata JSON;</li><li>pide al catálogo sustituir el puntero <code>v12 → v13</code>.</li></ol><p>Ese paso 2 es atómico <strong>en el catálogo</strong>. No afirmes que Iceberg “siempre commitea con rename de archivos” en S3/HDFS: Hadoop catalog, Hive, JDBC y REST implementan la atomicidad de formas distintas. Si el catálogo no puede hacer el swap de forma segura, dos writers se pisan.</p><h2 id="optimistic-concurrency" tabindex="-1">Optimistic concurrency <a class="header-anchor" href="#optimistic-concurrency" aria-label="Permalink to &quot;Optimistic concurrency&quot;">​</a></h2><p>Dos jobs pueden producir ficheros a la vez. Solo uno gana el puntero. El perdedor <strong>refresca</strong>, comprueba si su cambio sigue siendo válido (¿alguien tocó los mismos ficheros / el mismo snapshot base?) y <strong>reintenta</strong> si el motor lo contempla.</p><p>Un conflicto <strong>no</strong> se reintenta siempre en silencio. Un <code>MERGE</code> que leyó un snapshot ya inválido puede fallar: hay que relanzar la transacción. Dos streams o dos notebooks escribiendo la misma tabla sin coordinación van a chocar.</p><p>Elige el catálogo según <strong>cuántos motores y procesos</strong> commitean, no según el tutorial de <code>type=hadoop</code>.</p><p>Siguiente: <a href="./07-optimizacion">Optimización</a>.</p>`,26)])])}const u=e(n,[["render",r]]);export{m as __pageData,u as default};
